<?php

declare(strict_types=1);

namespace Lada\Core\Domain\Checkout;

use Lada\Core\Domain\Exception\InvalidIdentifier;

/**
 * Identifier of a checkout session, generated by Lada (UUID v4).
 */
final readonly class CheckoutSessionId
{
    private const string PATTERN = '/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\z/';

    private function __construct(
        public string $value,
    ) {}

    public static function generate(): self
    {
        $bytes = random_bytes(16);
        $bytes[6] = \chr(\ord($bytes[6]) & 0x0F | 0x40);
        $bytes[8] = \chr(\ord($bytes[8]) & 0x3F | 0x80);

        return new self(vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)));
    }

    public static function fromString(string $value): self
    {
        $normalized = strtolower($value);

        if (1 !== preg_match(self::PATTERN, $normalized)) {
            throw InvalidIdentifier::checkoutSessionId($value);
        }

        return new self($normalized);
    }

    public function equals(self $other): bool
    {
        return $this->value === $other->value;
    }

    public function __toString(): string
    {
        return $this->value;
    }
}
